#!/usr/bin/env python3
import os

BASE = "/Users/jimfu/Work/huixue/ziyuan_normalized"
SH_PATH = "/tmp/create_exact_dummies.sh"

mp4_b64 = ""
pptx_b64 = ""

with open(SH_PATH, "w") as f:
    f.write("#!/bin/bash\n")
    f.write("VOL_DIR='/var/lib/docker/volumes/ziyuan-data/_data'\n")
    f.write(f"cat << 'B64' > /tmp/dummy.mp4.b64\n{mp4_b64}\nB64\n")
    f.write(f"cat << 'B64' > /tmp/dummy.pptx.b64\n{pptx_b64}\nB64\n")
    f.write("base64 -d /tmp/dummy.mp4.b64 > /tmp/dummy.mp4\n")
    f.write("base64 -d /tmp/dummy.pptx.b64 > /tmp/dummy.pptx\n\n")

    for root, dirs, files in os.walk(BASE):
        if 'assets/videos' in root or 'assets/slides' in root:
            for file in files:
                if file.endswith('.mp4'):
                    rel_dir = os.path.relpath(root, BASE)
                    f.write(f"echo 'kejixueyuan@dashuju' | sudo -S mkdir -p \"$VOL_DIR/{rel_dir}\"\n")
                    f.write(f"echo 'kejixueyuan@dashuju' | sudo -S cp /tmp/dummy.mp4 \"$VOL_DIR/{rel_dir}/{file}\"\n")
                elif file.endswith('.pptx'):
                    rel_dir = os.path.relpath(root, BASE)
                    f.write(f"echo 'kejixueyuan@dashuju' | sudo -S mkdir -p \"$VOL_DIR/{rel_dir}\"\n")
                    f.write(f"echo 'kejixueyuan@dashuju' | sudo -S cp /tmp/dummy.pptx \"$VOL_DIR/{rel_dir}/{file}\"\n")
print(f"Generated {SH_PATH}")
